:root {
  --ink: #3d3028;
  --paper: #fffaf0;
  --crust: #c8753d;
  --cream: #f6e5bd;
  --sage: #55745d;
}

.feed-card {
  width: 440px;
  padding: 18px;
  border: 2px solid var(--ink);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.card-header,
.card-footer {
  display: flex;
  align-items: center;
}

.card-header {
  gap: 10px;
}

.mark {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border-radius: 12px;
  background: var(--cream);
  font-size: 22px;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--sage);
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

h1 {
  margin: 0;
  font-size: 20px;
  line-height: 1.1;
}

.badge {
  margin-left: auto;
  padding: 5px 9px;
  border-radius: 999px;
  background: var(--crust);
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
}

.note {
  margin: 16px 0;
  padding: 10px 12px;
  border-radius: 10px;
  background: var(--cream);
  font-size: 14px;
}

.card-footer {
  justify-content: space-between;
  color: var(--sage);
  font-size: 13px;
  font-weight: 700;
}

.card-footer button {
  border: 0;
  border-radius: 9px;
  padding: 9px 13px;
  background: var(--sage);
  color: var(--paper);
  font: inherit;
  cursor: pointer;
}
